pub(super)fn audit(p:&super::Program,ops:&[quantum_ecc::circuit::Op],outputs:&[usize],fixtures:&[serde_json::Value])->serde_json::Value{
 use quantum_ecc::sim::Simulator;use quantum_ecc::circuit::{analyze_ops,QubitOrBit};let curve=super::audit_curve();let(_,_,_,regs)=analyze_ops(ops.iter());let mut rows=vec![];let mut noise=0xa8d7135f23649b01u64;
 for(batch,inputs)in fixtures.chunks(64).enumerate(){let valid=if inputs.len()==64{u64::MAX}else{(1u64<<inputs.len())-1};let mut empty=super::AuditWords{v:vec![],at:0};let mut init=Simulator::new(p.nq,p.nb,&mut empty);let mut expected=vec![0u64;p.nq];for(lane,f)in inputs.iter().enumerate(){let k1=f["k1"].as_str().unwrap().parse().unwrap();let k2=f["k2"].as_str().unwrap().parse().unwrap();let a=curve.mul(curve.gx,curve.gy,k1);let b=curve.mul(curve.gx,curve.gy,k2);let e=curve.add(a.0,a.1,b.0,b.1);for(i,v)in[a.0,a.1,b.0,b.1].into_iter().enumerate(){init.set_register(&regs[i],v,lane);}for(i,v)in[e.0,e.1].into_iter().enumerate(){for(bit,item)in regs[i].iter().enumerate(){match item{QubitOrBit::Qubit(q)=>expected[q.0 as usize]|=(v.bit(bit)as u64)<<lane,_=>panic!("quantum outputs")}}}}let q=init.qubits.clone();let bits=init.bits.clone();drop(init);let start=std::time::Instant::now();let result=super::affine::eval(p,&q,&bits);let seconds=start.elapsed().as_secs_f64();let mut wrong=0;let mut known_bits=0u64;let mut fully_known=valid;for &q in outputs{let(z,o)=(result[q].z,result[q].o);known_bits+=((z|o)&valid).count_ones()as u64;fully_known&=z|o;wrong|=(o^expected[q])&(z|o)&valid;}let mut concrete=vec![];
  for pattern in 0..3{let words:Vec<u64>=(0..p.rng).map(|_|if pattern==0{0}else if pattern==1{u64::MAX}else{noise=noise.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);noise}).collect();let mut exact=q.clone();super::eval(p,&mut exact,&bits,&words);let mut rng=super::AuditWords{v:words.iter().flat_map(|v|v.to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);sim.qubits.copy_from_slice(&q);sim.bits.copy_from_slice(&bits);sim.apply_iter(ops.iter());let mut actual_wrong=0;for &q in outputs{assert_eq!(exact[q]&valid,sim.qubits[q]&valid,"numericIR/protected batch{batch} pattern{pattern} wire{q}");let tv=result[q];assert_eq!(sim.qubits[q]&(tv.z|tv.o)&valid,tv.o&valid,"ANF knownbit/protected mismatch");actual_wrong|=(sim.qubits[q]^expected[q])&valid;}assert_eq!(wrong&!actual_wrong,0,"false wrongpoint certificate");drop(sim);assert_eq!(rng.at,p.rng*8);concrete.push(serde_json::json!({"pattern":pattern,"wrong_mask":format!("{actual_wrong:016x}"),"wrong_shots":actual_wrong.count_ones()}));}
  rows.push(serde_json::json!({"batch":batch,"inputs":inputs.len(),"build_seconds":seconds,"known_output_bits":known_bits,"fully_known_shots":fully_known.count_ones(),"certified_wrong_shots":wrong.count_ones(),"certified_wrong_mask":format!("{wrong:016x}"),"protected_patterns":concrete,"protected_fullstream_comparisons":3}));eprintln!("WORD_PROOF_BATCH_COMPLETE batch={batch} known_bits={known_bits} certified_wrong={} seconds={seconds}",wrong.count_ones());
 }serde_json::json!({"status":"EXACT_SOURCE_NORMALIZED_ANF_VERIFIER_FIXTURE_AUDIT_NOT_A_NONCE_SCREEN","batches":rows,"fixtures":fixtures.len(),"nonce_screens":0,"nonce_rejections":0,"scope":"All original measurement words arbitrary64bit symbols. Constant masks, complete expression keys and exact Boolean identities only. Known output bits certify wrong values; unknown never rejects. Frozen oldsource/cache and fixed fixtures only, not a general currentparent filter or quantumrecord. Full originalFS qualification mandatory before any production rejection."})
}
